async function searchSamsClub(query) {
  await tool.navigate({ tabId, url: `https://www.samsclub.com/search?q=${encodeURIComponent(query)}` });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 8000 });
  return await browserjs(tabId, () => {
    const links = Array.from(document.querySelectorAll('a[href*="/ip/"]'));
    const items = [];
    const seen = new Set();
    for (const a of links) {
      const href = a.href.split('?')[0];
      const text = a.textContent.replace(/\s+/g, ' ').trim();
      if (!seen.has(href) && text.length > 5 && (text.includes('$') || text.includes('ct') || text.includes('pk') || text.includes('oz'))) {
        seen.add(href);
        items.push({ text, href });
      }
    }
    return items.slice(0, 10);
  });
}

