// Helper to open tab and wait for URL to commit
async function openAndVerifyTab(url) {
  const createRes = await tool.tabs_create({ url });
  const tabId = createRes.details.tabId;
  // Sleep 1.5s for tab to commit from blank
  await new Promise(r => setTimeout(r, 1500));
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 10000 });
  const pageRead = await browser.read({ tabId, maxChars: 2000 });
  return { tabId, text: pageRead.text };
}

